package io.github.ningpp.compat;

/** Replacement for System.Management.Automation.Host.PromptingException (generated by CSharpToJava converter). */
public class PromptingException extends HostException {
    public PromptingException() { super(); }
    public PromptingException(String message) { super(message); }
    public PromptingException(String message, Throwable cause) { super(message, cause); }
}
